import{z as p,x as E,o as l,c as A,q as i,j as s,D as t,d as r,s as o,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"前缀和与差分","description":"","frontmatter":{"title":"前缀和与差分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prefix-sum-difference.md","filePath":"cs/prefix-sum-difference.md","lastUpdated":1791413859000}'),m={name:"cs/prefix-sum-difference.md"};function B(D,a,f,h,u,c){const n=E("Mermaid");return l(),A("div",null,[a[2]||(a[2]=i('<h1 id="前缀和与差分" tabindex="-1">前缀和与差分 <a class="header-anchor" href="#前缀和与差分" aria-label="Permalink to &quot;前缀和与差分&quot;">​</a></h1><div class="epigraph"><p>把每个位置改成「从左端扫到这里的合计」，区间和就变成两次查表相减；差分是它的逆运算，把区间加变成两端各改一次。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms；Sedgewick and Wayne, Algorithms 整理</footer></div><p><a href="/cs/planar-graph">上一课</a>把平面图直觉钉下：简单平面图 \\(m=O(n)\\)，来自欧拉公式与面的度数，表示仍是稀疏邻接。主干里<a href="/cs/array-random-access">数组与随机访问</a>已经给出按下标 \\(\\Theta(1)\\) 读写，但没有把「一段连续下标的合计」收成预处理结构。本课起数据结构进阶：不重开推测执行，也不重讲地址公式。缺口是：静态数组上的区间和、以及区间加完再读点值——用前缀和与差分数组，而不是每次扫描。后课默认已经读完这里：静态区间和是 \\(O(1)\\) 查询，\\(O(n)\\) 预处理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 元数组 \\(A\\)，多次问 \\(\\sum_{i=l}^{r} A[i]\\)。每次扫 \\([l,r]\\) 是 \\(\\Theta(r-l+1)\\)，查询多了不可接受。缺口不是新的存储模型，而是<strong>一次从左到右的合计表</strong> \\(S[i]=\\sum_{j=1}^{i}A[j]\\)（\\(S[0]=0\\)），使</p> \\[\\sum_{i=l}^{r} A[i] = S[r]-S[l-1]. \\]<p>对偶问题：多次对 \\([l,r]\\) 同时加 \\(d\\)，最后读每个点。若每次把区间扫一遍，总代价随更新长度涨。差分 \\(D[1]=A[1]\\)，\\(D[i]=A[i]-A[i-1]\\)（\\(i\\gt 1\\)）把区间加变成 \\(D[l]\\mathrel{+}=d\\)、\\(D[r+1]\\mathrel{-}=d\\)，再前缀和还原 \\(A\\)。</p><p><span class="marginnote">前缀和是扫描的记录；差分是离散导数。二维前缀和（容斥四角）同构，本课先钉一维，后课线段树再谈可变数组。</span></p><p><span class="marginnote">直觉类比：前缀和像里程表——每个数记的是「从起点到这里累计走了多远」，问任意两站之间的距离，只需两个读数相减，不用把路重走一遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理：从左扫一遍写 \\(S\\)，时间 \\(\\Theta(n)\\)，额外 \\(\\Theta(n)\\) 字。查询两次随机访问。差分更新：合法下标上两次写；全部更新结束后对 \\(D\\) 做一次前缀和得到最终 \\(A\\)。不要在「尚未还原」的 \\(D\\) 上直接当点值用，除非合同写明读的是差分数组本身。</p>',11)),(l(),s(d,null,{default:t(()=>[o(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%95%B0%E7%BB%84%20A%22%5D%20--%3E%20S%5B%22%E5%89%8D%E7%BC%80%E5%92%8C%20S%22%5D%0A%20%20S%20--%3E%20Q%5B%22S%5Br%5D%20-%20S%5Bl-1%5D%22%5D%0A%20%20D%5B%22%E5%B7%AE%E5%88%86%20D%22%5D%20--%3E%20A2%5B%22%E5%89%8D%E7%BC%80%E8%BF%98%E5%8E%9F%20A%22%5D%0A%20%20U%5B%22%E5%8C%BA%E9%97%B4%E5%8A%A0%22%5D%20--%3E%20D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[r("与"),e("a",{href:"/cs/amortized-analysis"},"摊还分析"),r("无关：这里每次查询最坏已是 \\(\\Theta(1)\\)，没有峰值要摊。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"正确性就是和的结合律与减法消去。下标约定必须全局一致：从 \\(0\\) 还是从 \\(1\\)，以及空区间 \\(l\\gt r\\) 是否定义为 \\(0\\)。溢出：合计宽度要能装下 \\(n\\) 倍元素上界，否则环绕会把区间和证伪。",-1)),a[6]||(a[6]=e("p",null,"差分与前缀互逆：对 \\(A\\) 取差分再前缀，得到 \\(A\\)；对 \\(D\\) 取前缀再差分，得到 \\(D\\)。区间加只动两端，是因为中间的差分不变——相邻差没变，整段被抬高同一常数。",-1)),a[7]||(a[7]=e("p",null,"用一个全 0 数组把「区间加只动两端」走一遍，看清还原后中间整段被抬起：",-1)),(l(),s(d,null,{default:t(()=>[o(n,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20Z%5B%22%E5%88%9D%E5%A7%8B%20D%EF%BC%9A0%200%200%200%200%22%5D%20--%3E%20UP%5B%22%E5%AF%B9%E5%8C%BA%E9%97%B4%202..4%20%E5%8A%A0%205%3Cbr%2F%3ED%5B2%5D%2B%3D5%20%E4%B8%94%20D%5B5%5D-%3D5%22%5D%0A%20%20UP%20--%3E%20ARR%5B%22%E6%94%B9%E5%90%8E%20D%EF%BC%9A0%205%200%200%20-5%22%5D%0A%20%20ARR%20--%3E%20PS%5B%22%E5%AF%B9%20D%20%E5%81%9A%E5%89%8D%E7%BC%80%E5%92%8C%E8%BF%98%E5%8E%9F%22%5D%0A%20%20PS%20--%3E%20RES%5B%22A%EF%BC%9A0%205%205%205%200%3Cbr%2F%3E%E4%B8%AD%E9%97%B4%E6%95%B4%E6%AE%B5%E6%8A%AC%E9%AB%98%205%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">数字实例：数组全 0，对 [2,4] 整段加 5，只写两次——D[2] 加 5、D[5] 减 5；前缀和还原后得到 0,5,5,5,0。若逐点扫区间要写 3 次，区间越长差距越大。</span></p><p>顺序扫写 \\(S\\) 吃<a href="/cs/locality-principle">局部性</a>；查询两次随机读，cache 行为取决于 \\(l,r\\) 是否跳。本课不把这当成外存 B 树问题。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>前缀和要求<strong>可结合、有逆</strong>的区间贡献（通常是加法群）。最大值、最大公因数没有群逆，不能靠两次查表相减得到任意区间——那是下一课稀疏表的入口。数组中途被单点改掉，\\(S\\) 全表作废，需要树状数组或线段树，本课不提前写。</p><p>后课默认：静态加法区间用前缀和；静态幂等查询另找倍增表。</p><p><span class="marginnote">常见误区：初学者容易把「两次查表相减」套到最大值上——max(1..r) 减 max(1..l-1) 什么都不是。能相减的前提是运算可结合且有逆（加法满足，max 不满足），无逆的聚合要用别的结构。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前缀和：\\(O(n)\\) 预处理，\\(O(1)\\) 区间和。</li><li>差分：区间加变成两端点更新，再前缀还原。</li><li>需要群运算；无逆的聚合留给稀疏表。</li><li>出处：Cormen et al.；Sedgewick and Wayne。</li></ul>',8))])}const g=p(m,[["render",B]]);export{_ as __pageData,g as default};
